```javascript
// Fragment shader for the heart fractal
var fragShader = `
  precision highp float;

  uniform vec2 resolution;
  uniform float time;

  void main() {
    vec2 uv = gl_FragCoord.xy / resolution.xy;
    uv -= .5;
    uv *= vec2(1, -1);

    vec3 color = vec3(1, 0, 0); // Initial color (red)

    // Heart shape
    float distance = length(uv * vec2(1, 3) * sin(time * 0.1) + vec2(0, 0.5));
    distance *= distance;
    distance *= 3.0;

    // Iterate fractal points
    for (int i = 0; i < 5; i++) {
      vec2 p = (uv * vec2(1, 2) * cos(time * 0.1) + vec2(0, 0.5));
      p *= sin(time * 0.1) + 1.0;
      p -= vec2(0, 0.25);
      p /= distance * 10.0;
      distance = length(p * vec2(1, 2) * cos(time * 0.1) + vec2(0, 0.5));
      distance *= distance;
      distance *= 3.0;

      // Add some noise to the fractal
      distance += sin(time * 0.1 + p.x * 0.1 + p.y * 0.01);
    }

    // Apply contrast and saturation to the fractal
    color.rgb *= pow(max(dot(uv, vec2(0, 1.0)), 0.0), 5.0);
    color.rgb *= vec3(1 + i * 0.5);
    color.rgb *= vec3(1.5 - i * 0.2);

    gl_FragColor = vec4(color, 1.0);
  }
`;

