}
```

**Paso 4: Detectar pares de tiles**

En el script "Match3Game", crea un método que se encargue de detectar pares de tiles que pueden ser cambiados. Puedes hacer esto utilizando el siguiente código:

```csharp
void CheckForMatches()
{
    for (int x = 0; x < gridSizeX; x++)
    {
        for (int y = 0; y < gridSizeY; y++)
        {
            Tile tile = tiles.Find(t => t.x == x && t.y == y);
            if (tile != null)
            {
                // Detectar pares de tiles en horizontal
                for (int i = 1; i < 4; i++)
                {
                    Tile neighbor = tiles.Find(t => t.x == x && t.y == y + i);
                    if (neighbor != null && tile.color == neighbor.color)
                    {
                        // Se ha encontrado un par de tiles que pueden ser cambiados
                        // Por ejemplo, puedes cambiar el color de los tiles
                        tile.color = Color.green;
                        neighbor.color = Color.green;
                    }
                }

                // Detectar pares de tiles en vertical
                for (int i = 1; i < 4; i++)
                {
                    Tile neighbor = tiles.Find(t => t.x == x + i && t.y == y);
                    if (neighbor != null && tile.color == neighbor.color)
                    {
                        // Se ha encontrado un par de tiles que pueden ser cambiados
                        // Por ejemplo, puedes cambiar el color de los tiles
                        tile.color = Color.green;
                        neighbor.color = Color.green;
                    }
                }
            }
        }
    }
}
```

**Paso 5: Manejar el despliegue de nuevos tiles**

En el script "Match3Game", crea un método que se encargue de desplegar nuevos tiles en la grid cuando un par de tiles sea cambiado. Puedes hacer esto utilizando el siguiente código:

```csharp
void SpawnNewTile()
{
