using System;
using System.Net;
using System.IO;

class HelloWorldServer
{
    static void Main(string[] args)
    {
        HttpListener listener = new HttpListener();
        listener.Prefixes.Add("http://*:8080/hello");

        listener.Start();

        Console.WriteLine("Server started. Listening for incoming requests...");

        while (true)
        {
            HttpListenerContext context = listener.GetContext();
            HttpListenerRequest request = context.Request;

            if (request.HttpMethod == "GET" && request.Url.AbsolutePath == "/hello")
            {
                string response = "Hello";
                byte[] buffer = System.Text.Encoding.UTF8.GetBytes(response);

                context.Response.ContentType = "text/plain";
                context.Response.ContentLength64 = buffer.Length;
                context.Response.OutputStream.Write(buffer, 0, buffer.Length);
                context.Response.OutputStream.Close();
            }
            else
            {
                context Response.WriteLine("Invalid request");
                context.Response.Close();
            }
        }
    }
}
```
Explications :

* Nous créons un objet `HttpListener` et configurons le prefix d'écoute avec `Prefixes.Add("http://*:8080/hello")`. Le `*` signifie que le serveur peut être exécuté sur n'importe quel ordinateur de la réseau, et `http://192.168.1.100:8080/hello` spécifie que nous allons écouter les requêtes HTTP GET sur la page `/hello` sur le port 8080.
* Nous começons le serveur avec `listener.Start()`.
* Nous utilisons un boucle infinie pour attendre les requêtes et les traiter. Pour chaque requête, nous vérifions si elle est une requête GET et si elle est pour la page `/hello`. Si c'est le cas, nous créons un réponse avec le texte "Hello" et l'envoyons au client.
* Si la requête n'est pas une requête GET ou si elle n'est pas pour la page `/hello`, nous envoyons une réponse d'erreur au client.

